#!/usr/bin/env python3
# Generates internal/ipmi/ipmitool_tables_gen.go from ipmitool's own C
# tables, so fyrtaarn's native event log reads as ipmitool's "sel list":
#   include/ipmitool/ipmi_sel.h  generic_event_types, sensor_specific_event_types
#   lib/ipmi_strings.c           ipmi_generic_sensor_type_vals
#
# Usage: scripts/gen-ipmi-tables.py <ipmitool source dir> <tag>
#   e.g. scripts/gen-ipmi-tables.py ~/src/ipmitool IPMITOOL_1_8_19
#
# ipmitool is under Sun's BSD-3 licence, whose notice must stay with code
# derived from it; the generated file carries it.

import re
import sys
from pathlib import Path

NOTICE = """\
// Derived from ipmitool (https://github.com/ipmitool/ipmitool), %s,
// include/ipmitool/ipmi_sel.h and lib/ipmi_strings.c, under this licence:
//
// Copyright (c) 2003 Sun Microsystems, Inc.  All Rights Reserved.
//
// Redistribution and use in source and binary forms, with or without
// modification, are permitted provided that the following conditions
// are met:
//
// Redistribution of source code must retain the above copyright
// notice, this list of conditions and the following disclaimer.
//
// Redistribution in binary form must reproduce the above copyright
// notice, this list of conditions and the following disclaimer in the
// documentation and/or other materials provided with the distribution.
//
// Neither the name of Sun Microsystems, Inc. or the names of
// contributors may be used to endorse or promote products derived
// from this software without specific prior written permission.
//
// This software is provided "AS IS," without a warranty of any kind.
// ALL EXPRESS OR IMPLIED CONDITIONS, REPRESENTATIONS AND WARRANTIES,
// INCLUDING ANY IMPLIED WARRANTY OF MERCHANTABILITY, FITNESS FOR A
// PARTICULAR PURPOSE OR NON-INFRINGEMENT, ARE HEREBY EXCLUDED.
// SUN MICROSYSTEMS, INC. ("SUN") AND ITS LICENSORS SHALL NOT BE LIABLE
// FOR ANY DAMAGES SUFFERED BY LICENSEE AS A RESULT OF USING, MODIFYING
// OR DISTRIBUTING THIS SOFTWARE OR ITS DERIVATIVES.  IN NO EVENT WILL
// SUN OR ITS LICENSORS BE LIABLE FOR ANY LOST REVENUE, PROFIT OR DATA,
// OR FOR DIRECT, INDIRECT, SPECIAL, CONSEQUENTIAL, INCIDENTAL OR
// PUNITIVE DAMAGES, HOWEVER CAUSED AND REGARDLESS OF THE THEORY OF
// LIABILITY, ARISING OUT OF THE USE OF OR INABILITY TO USE THIS SOFTWARE,
// EVEN IF SUN HAS BEEN ADVISED OF THE POSSIBILITY OF SUCH DAMAGES.
"""

ENTRY = re.compile(r'\{\s*(0x[0-9A-Fa-f]+|\d+)\s*,\s*(0x[0-9A-Fa-f]+|\d+)\s*,\s*(0x[0-9A-Fa-f]+|\d+)\s*,\s*("(?:[^"\\]|\\.)*"|NULL)\s*\}')
STRING = re.compile(r'"((?:[^"\\]|\\.)*)"')


def table(src, name):
  m = re.search(r'\b' + re.escape(name) + r'\[\]\s*=\s*\{', src)
  if not m:
    sys.exit("table %s not found" % name)
  end = src.index('};', m.end())
  return src[m.end():end]


def strip_comments(s):
  return re.sub(r'/\*.*?\*/', '', s, flags=re.S)


def event_table(src, name):
  rows = []
  for code, offset, data, desc in ENTRY.findall(strip_comments(table(src, name))):
    if desc == 'NULL':
      continue
    rows.append((int(code, 0), int(offset, 0), int(data, 0), desc))
  if not rows:
    sys.exit("table %s is empty" % name)
  return rows


def main():
  if len(sys.argv) != 3:
    sys.exit(__doc__ if __doc__ else "usage: gen-ipmi-tables.py <ipmitool dir> <tag>")
  root, tag = Path(sys.argv[1]), sys.argv[2]
  sel = (root / 'include/ipmitool/ipmi_sel.h').read_text()
  strings = (root / 'lib/ipmi_strings.c').read_text()

  generic = event_table(sel, 'generic_event_types')
  specific = event_table(sel, 'sensor_specific_event_types')
  types = STRING.findall(strip_comments(table(strings, 'ipmi_generic_sensor_type_vals')))

  out = ["// Code generated by scripts/gen-ipmi-tables.py; DO NOT EDIT.", "", NOTICE % tag, "package ipmi", ""]
  out.append("// ipmitoolTablesTag is the ipmitool release the tables were taken from.")
  out.append('const ipmitoolTablesTag = "%s"' % tag)
  out.append("")
  for name, rows, what in (("genericEventTypes", generic, "generic_event_types (by event/reading type)"),
                           ("sensorSpecificEventTypes", specific, "sensor_specific_event_types (by sensor type, event/reading type 0x6f)")):
    out.append("// %s is ipmitool's %s, in its order." % (name, what))
    out.append("var %s = []eventDesc{" % name)
    for code, offset, data, desc in rows:
      out.append("\t{0x%02x, 0x%02x, 0x%02x, %s}," % (code, offset, data, desc))
    out.append("}")
    out.append("")
  out.append("// genericSensorTypes is ipmitool's ipmi_generic_sensor_type_vals, indexed by sensor type.")
  out.append("var genericSensorTypes = []string{")
  for t in types:
    out.append('\t"%s",' % t)
  out.append("}")
  out.append("")
  Path('internal/ipmi/ipmitool_tables_gen.go').write_text("\n".join(out))
  print("generic %d, sensor-specific %d, sensor types %d" % (len(generic), len(specific), len(types)))


main()
